('script_welcome','script','أول رسالة','أهلًا بيكي في رونق. أكيد أساعدك، إيه الهدف اللي تحبي توصلي له؟',1,'{}'),
('script_fixed_price','script','سعر ثابت ومعتمد','السعر هو [السعر المعتمد]. تحبي أوضحلك تفاصيل الخدمة والخطوة المناسبة لهدفك؟',2,'{}'),
('script_variable_price','script','سعر متغير','السعر بيتحدد حسب [العامل المعتمد]. لو تحبي، نفهم هدفك ونوضحلك خطوات التقييم.',3,'{}'),
('script_discovery','script','فهم الاحتياج','إيه الهدف اللي تحبي توصلي له؟ وفي حاجة معينة حابة نفهمها أكتر قبل ما نوضح الخطوة الجاية؟',4,'{}'),
('script_trust','script','بعد فهم الاحتياج','تمام، فهمت قصدك. نبدأ بتقييم مع الطبيبة علشان نعرف أنسب اختيار ليكي، وهل فور بلس مناسب لهدفك فعلًا.',5,'{}'),
('script_booking','script','عرض الحجز','عندنا [موعد متاح أول] و[موعد متاح ثانٍ] بعد مراجعة جدول المركز. أنهي أنسب ليكي؟',6,'{}'),
('script_followup','script','متابعة مرتبطة بالاحتياج','براجع معاكي بخصوص [الهدف اللي ذكرتيه]. في نقطة تحبي نوضحها، ولا تحبي نراجع معاكي موعد مناسب للتقييم؟',7,'{}'),
('script_confirmation','script','تأكيد الحجز','بنأكد معاكي حجزك يوم [اليوم] الساعة [الوقت] في [العنوان المعتمد]. هل الموعد مناسب؟',8,'{}'),
('script_noshow','script','بعد عدم الحضور','حبيت أطمن عليكي، كان عندك موعد معانا. لو حصل ظرف، نقدر نراجع المتاح ونرتبلك موعد تاني يناسبك.',9,'{}'),
('script_think','script','محتاجة تفكر','أكيد براحتك. إيه أكتر حاجة محتاجة تكون واضحة عندك قبل ما تقرري؟',10,'{}'),
('script_noanswer','script','لا ترد','لو الوقت مش مناسب دلوقتي، تحبي نرجع نتواصل معاكي في وقت أنسب؟',11,'{}'),
('setting_sla','setting','هدف الرد المذكور في المصدر','المستهدف ٥ دقائق، والمقبول حتى ١٠ أثناء ساعات العمل. ساعات العمل لم تُعتمد؛ المعروض حاليًا زمن فعلي منذ الاستفسار وليس زمنًا داخل ساعات العمل.',1,'{"target_minutes":5,"acceptable_minutes":10,"business_hours_verified":false,"evidence":"Reported"}'),
('setting_followup','setting','توقيت المتابعة','حسب السياق في نفس اليوم، ثم اليوم التالي، ثم بعد يومين إلى ثلاثة. لا توجد رسائل آلية. يُراجع الموعد والموافقة قبل أي تواصل.',2,'{"evidence":"Reported"}'),
('setting_limits','setting','بيانات تحتاج اعتماد الإدارة','أسعار الخدمات، عنوان المركز، ساعات العمل، جدول الإتاحة، سياسة التأكيد، وأسماء الموظفات غير موجودة في المصدر. لا تُستخدم قيم مفترضة.',3,'{"evidence":"Unknown"}')
